// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address caller, address providedNft) public {
        vm.assume(caller != address(0));
        vm.assume(providedNft != address(0));

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bool ok;
        try c.initialize(address(0), providedNft, 1, 1, 0, 0, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || c.nft() == providedNft);
    }
}
